from datetime import datetime, timedelta
import pytest
from isoduration import add_duration


class TestValidBasicFormats:
    """Test parsing and application of valid ISO 8601 durations."""

    def test_single_day(self):
        assert add_duration(datetime(2025, 3, 10), "P1D") == datetime(2025, 3, 11)

    def test_single_month(self):
        assert add_duration(datetime(2025, 3, 10), "P1M") == datetime(2025, 4, 10)

    def test_single_year(self):
        assert add_duration(datetime(2025, 3, 10), "P1Y") == datetime(2026, 3, 10)

    def test_single_week(self):
        assert add_duration(datetime(2025, 3, 10), "P1W") == datetime(2025, 3, 17)

    def test_single_hour(self):
        assert add_duration(datetime(2025, 3, 10, 8), "PT1H") == datetime(2025, 3, 10, 9)

    def test_single_minute(self):
        assert add_duration(datetime(2025, 3, 10, 8), "PT1M") == datetime(2025, 3, 10, 8, 1)

    def test_single_second(self):
        assert add_duration(datetime(2025, 3, 10, 8), "PT1S") == datetime(2025, 3, 10, 8, 0, 1)

    def test_multiple_date_components(self):
        # P1Y2M3D
        result = add_duration(datetime(2024, 1, 1), "P1Y2M3D")
        assert result == datetime(2025, 3, 4)

    def test_multiple_time_components(self):
        # PT1H2M3S
        result = add_duration(datetime(2025, 3, 10, 0, 0, 0), "PT1H2M3S")
        assert result == datetime(2025, 3, 10, 1, 2, 3)

    def test_all_components(self):
        # P1Y2M3DT4H5M6S
        result = add_duration(datetime(2024, 1, 1, 0, 0, 0), "P1Y2M3DT4H5M6S")
        # 2024-01-01 + 1Y2M = 2025-03-01
        # 2025-03-01 + 3D = 2025-03-04
        # 2025-03-04 + 4H5M6S = 2025-03-04 04:05:06
        assert result == datetime(2025, 3, 4, 4, 5, 6)

    def test_with_plus_sign(self):
        assert add_duration(datetime(2025, 3, 10), "+P1D") == datetime(2025, 3, 11)

    def test_with_minus_sign(self):
        assert add_duration(datetime(2025, 3, 10), "-P1D") == datetime(2025, 3, 9)

    def test_leading_zeros(self):
        assert add_duration(datetime(2025, 3, 10), "P01D") == datetime(2025, 3, 11)
        assert add_duration(datetime(2025, 3, 10), "P001D") == datetime(2025, 3, 11)


class TestSyntaxErrors:
    """Test that invalid syntax raises ValueError."""

    def test_p_missing(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "1D")

    def test_no_components(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P")

    def test_t_without_time_component(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "PT")

    def test_p_with_t_only_no_date_or_time(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1DT")

    def test_whitespace_in_duration(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P 1D")

    def test_whitespace_after_p(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P 1D")

    def test_sign_on_component(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P-1D")

    def test_lowercase_p(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "p1D")

    def test_lowercase_designators(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1d")

    def test_lowercase_t(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1Dt1H")

    def test_decimal_digit_missing_right(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "PT1.S")

    def test_decimal_digit_missing_left(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "PT.5S")


class TestComponentOrdering:
    """Test that components must appear in the correct order."""

    def test_day_before_month_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1D1M")

    def test_day_before_year_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1D1Y")

    def test_month_before_year_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1M1Y")

    def test_minute_before_hour_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "PT1M1H")

    def test_second_before_minute_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "PT1S1M")

    def test_time_component_before_t_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1HT1D")

    def test_correct_order_all_components(self):
        # P1Y2M3DT4H5M6S is valid
        result = add_duration(datetime(2024, 1, 1, 0, 0, 0), "P1Y2M3DT4H5M6S")
        assert result == datetime(2025, 3, 4, 4, 5, 6)


class TestDuplicateComponents:
    """Test that duplicate components are rejected."""

    def test_duplicate_days(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1D2D")

    def test_duplicate_months(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1M2M")

    def test_duplicate_years(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1Y2Y")

    def test_duplicate_weeks(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1W2W")

    def test_duplicate_hours(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "PT1H2H")

    def test_duplicate_minutes(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "PT1M2M")

    def test_duplicate_seconds(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "PT1S2S")


class TestFractions:
    """Test fraction handling and validation."""

    def test_fraction_on_seconds(self):
        result = add_duration(datetime(2025, 3, 10), "PT1.5S")
        assert result == datetime(2025, 3, 10, 0, 0, 1, 500000)

    def test_fraction_on_minutes(self):
        result = add_duration(datetime(2025, 3, 10), "PT1.5M")
        assert result == datetime(2025, 3, 10, 0, 1, 30)

    def test_fraction_on_hours(self):
        result = add_duration(datetime(2025, 3, 10), "PT1.5H")
        assert result == datetime(2025, 3, 10, 1, 30)

    def test_fraction_on_days(self):
        result = add_duration(datetime(2025, 3, 10), "P1.5D")
        assert result == datetime(2025, 3, 11, 12)

    def test_comma_as_decimal_separator_seconds(self):
        result = add_duration(datetime(2025, 3, 10), "PT1,5S")
        assert result == datetime(2025, 3, 10, 0, 0, 1, 500000)

    def test_comma_as_decimal_separator_days(self):
        result = add_duration(datetime(2025, 3, 10), "P1,5D")
        assert result == datetime(2025, 3, 11, 12)

    def test_fraction_on_months_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1.5M")

    def test_fraction_on_years_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1.5Y")

    def test_fraction_not_on_last_component(self):
        # P1.5D1T1H is invalid because D is not last
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1.5DT1H")

    def test_fraction_not_on_last_time_component(self):
        # P1D1.5HT1M is invalid syntax, but P1DT1.5H1M is invalid because H is not last
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1DT1.5H1M")


class TestWeekRestrictions:
    """Test that weeks cannot be combined with other components."""

    def test_week_alone_valid(self):
        result = add_duration(datetime(2025, 3, 10), "P1W")
        assert result == datetime(2025, 3, 17)

    def test_week_with_days_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1W1D")

    def test_week_with_months_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1W1M")

    def test_week_with_years_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1W1Y")

    def test_fractional_week(self):
        # P0.5W = 3.5 days
        expected = datetime(2025, 3, 10) + timedelta(days=3.5)
        result = add_duration(datetime(2025, 3, 10), "P0.5W")
        assert result == expected


class TestMonthYearCalculations:
    """Test month and year component calculations with day-of-month adjustments."""

    def test_add_one_month_basic(self):
        assert add_duration(datetime(2025, 3, 15), "P1M") == datetime(2025, 4, 15)

    def test_add_one_year_basic(self):
        assert add_duration(datetime(2025, 3, 15), "P1Y") == datetime(2026, 3, 15)

    def test_month_overflow_31_to_28_non_leap(self):
        # 2025-01-31 + P1M = 2025-02-28 (Feb has 28 days)
        result = add_duration(datetime(2025, 1, 31), "P1M")
        assert result == datetime(2025, 2, 28)

    def test_month_overflow_31_to_29_leap_year(self):
        # 2024-01-31 + P1M = 2024-02-29 (leap year)
        result = add_duration(datetime(2024, 1, 31), "P1M")
        assert result == datetime(2024, 2, 29)

    def test_month_overflow_31_to_30(self):
        # 2024-03-31 + P1M = 2024-04-30 (April has 30 days)
        result = add_duration(datetime(2024, 3, 31), "P1M")
        assert result == datetime(2024, 4, 30)

    def test_year_and_month_together_as_total_months(self):
        # 2024-02-29 + P1Y1M should move by 13 months total, not year then month
        result = add_duration(datetime(2024, 2, 29), "P1Y1M")
        assert result == datetime(2025, 3, 29)

    def test_multiple_months(self):
        # 2024-01-31 + P2M = 2024-03-31
        result = add_duration(datetime(2024, 1, 31), "P2M")
        assert result == datetime(2024, 3, 31)

    def test_twelve_months_equals_one_year(self):
        # 2024-03-15 + P12M = 2025-03-15
        result = add_duration(datetime(2024, 3, 15), "P12M")
        assert result == datetime(2025, 3, 15)

    def test_month_preserves_time(self):
        # Time components should be preserved when applying month/year
        result = add_duration(datetime(2025, 1, 31, 15, 30, 45), "P1M")
        assert result == datetime(2025, 2, 28, 15, 30, 45)


class TestNegativeDurations:
    """Test applying negative durations."""

    def test_negative_days(self):
        assert add_duration(datetime(2025, 3, 10), "-P1D") == datetime(2025, 3, 9)

    def test_negative_months(self):
        assert add_duration(datetime(2025, 3, 15), "-P1M") == datetime(2025, 2, 15)

    def test_negative_years(self):
        assert add_duration(datetime(2025, 3, 15), "-P1Y") == datetime(2024, 3, 15)

    def test_negative_hours(self):
        result = add_duration(datetime(2025, 3, 10, 10, 0, 0), "-PT1H")
        assert result == datetime(2025, 3, 10, 9, 0, 0)

    def test_negative_month_overflow_leap_year(self):
        # 2024-03-31 - P1M = 2024-02-29 (Feb has 29 days in leap year)
        result = add_duration(datetime(2024, 3, 31), "-P1M")
        assert result == datetime(2024, 2, 29)

    def test_negative_month_overflow_non_leap(self):
        # 2025-03-31 - P1M = 2025-02-28
        result = add_duration(datetime(2025, 3, 31), "-P1M")
        assert result == datetime(2025, 2, 28)

    def test_negative_combined_month_and_day(self):
        # 2024-03-01 - P1M1D: first back 1M to 2024-02-01, then back 1D
        result = add_duration(datetime(2024, 3, 1), "-P1M1D")
        assert result == datetime(2024, 1, 31)

    def test_negative_time_components(self):
        result = add_duration(datetime(2025, 3, 10, 5, 30, 10), "-PT1H2M3S")
        assert result == datetime(2025, 3, 10, 4, 28, 7)


class TestTimeComponentsApplication:
    """Test application of time components."""

    def test_add_multiple_hours(self):
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT2H")
        assert result == datetime(2025, 3, 10, 10, 0, 0)

    def test_add_multiple_minutes(self):
        result = add_duration(datetime(2025, 3, 10, 8, 30, 0), "PT15M")
        assert result == datetime(2025, 3, 10, 8, 45, 0)

    def test_add_multiple_seconds(self):
        result = add_duration(datetime(2025, 3, 10, 8, 0, 30), "PT30S")
        assert result == datetime(2025, 3, 10, 8, 1, 0)

    def test_time_overflow_to_next_day(self):
        result = add_duration(datetime(2025, 3, 10, 23, 0, 0), "PT2H")
        assert result == datetime(2025, 3, 11, 1, 0, 0)

    def test_time_negative_overflow_to_previous_day(self):
        result = add_duration(datetime(2025, 3, 10, 1, 0, 0), "-PT2H")
        assert result == datetime(2025, 3, 9, 23, 0, 0)


class TestDaysAndWeeks:
    """Test application of days and weeks."""

    def test_add_multiple_days(self):
        result = add_duration(datetime(2025, 3, 10), "P10D")
        assert result == datetime(2025, 3, 20)

    def test_add_multiple_weeks(self):
        result = add_duration(datetime(2025, 3, 10), "P2W")
        assert result == datetime(2025, 3, 24)

    def test_fractional_day_exact_time(self):
        # P0.5D = 12 hours
        result = add_duration(datetime(2025, 3, 10, 0, 0, 0), "P0.5D")
        assert result == datetime(2025, 3, 10, 12, 0, 0)

    def test_fractional_hours_exact_time(self):
        # PT0.5H = 30 minutes
        result = add_duration(datetime(2025, 3, 10, 0, 0, 0), "PT0.5H")
        assert result == datetime(2025, 3, 10, 0, 30, 0)

    def test_fractional_minutes_exact_time(self):
        # PT0.5M = 30 seconds
        result = add_duration(datetime(2025, 3, 10, 0, 0, 0), "PT0.5M")
        assert result == datetime(2025, 3, 10, 0, 0, 30)

    def test_fractional_weeks(self):
        # P1.5W = 10.5 days
        expected = datetime(2025, 3, 10) + timedelta(days=10.5)
        result = add_duration(datetime(2025, 3, 10), "P1.5W")
        assert result == expected


class TestComplexScenarios:
    """Test complex combinations of components."""

    def test_weeks_plus_time(self):
        # P1W1DT... is invalid (W with other date components)
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1W1D")

    def test_multiple_months_with_time(self):
        result = add_duration(datetime(2024, 1, 15, 10, 0, 0), "P2M5DT3H30M")
        # 2024-01-15 + 2M = 2024-03-15
        # 2024-03-15 + 5D = 2024-03-20
        # 2024-03-20 10:00 + 3H30M = 2024-03-20 13:30
        assert result == datetime(2024, 3, 20, 13, 30)

    def test_year_month_day_time_combined(self):
        result = add_duration(datetime(2024, 1, 15, 8, 30, 15), "P1Y2M3DT4H5M6S")
        # 2024-01-15 + 1Y2M = 2025-03-15
        # 2025-03-15 + 3D = 2025-03-18
        # 2025-03-18 08:30:15 + 4H5M6S = 2025-03-18 12:35:21
        assert result == datetime(2025, 3, 18, 12, 35, 21)

    def test_order_of_operations_month_then_days(self):
        # Months are applied first, which can affect day-of-month
        result = add_duration(datetime(2024, 3, 31), "P1M2D")
        # 2024-03-31 + 1M = 2024-04-30 (April only has 30 days)
        # 2024-04-30 + 2D = 2024-05-02
        assert result == datetime(2024, 5, 2)


class TestDatetimeBoundaries:
    """Test behavior at datetime limits."""

    def test_max_datetime_overflow(self):
        # datetime.max is 9999-12-31 23:59:59.999999
        # Adding beyond this should raise ValueError
        with pytest.raises(ValueError):
            add_duration(datetime(9999, 12, 31), "P1D")

    def test_min_datetime_underflow(self):
        # datetime.min is 0001-01-01 00:00:00
        # Subtracting beyond this should raise ValueError
        with pytest.raises(ValueError):
            add_duration(datetime(1, 1, 1), "-P1D")

    def test_near_max_no_overflow(self):
        result = add_duration(datetime(9999, 12, 30), "P1D")
        assert result == datetime(9999, 12, 31)

    def test_near_min_no_underflow(self):
        result = add_duration(datetime(1, 1, 2), "-P1D")
        assert result == datetime(1, 1, 1)

    def test_year_boundary_overflow(self):
        result = add_duration(datetime(9999, 12, 31), "PT1S")
        with pytest.raises(ValueError):
            add_duration(datetime(9999, 12, 31, 23, 59, 59, 999999), "PT1S")


class TestZeroAndLargeValues:
    """Test zero values and large component values."""

    def test_zero_days(self):
        result = add_duration(datetime(2025, 3, 10), "P0D")
        assert result == datetime(2025, 3, 10)

    def test_zero_hours(self):
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT0H")
        assert result == datetime(2025, 3, 10, 8, 0, 0)

    def test_large_days(self):
        result = add_duration(datetime(2025, 1, 1), "P1000D")
        expected = datetime(2025, 1, 1) + timedelta(days=1000)
        assert result == expected

    def test_large_months(self):
        # 100 months = 8 years 4 months
        result = add_duration(datetime(2000, 1, 1), "P100M")
        assert result == datetime(2008, 5, 1)


class TestMicrosecondPrecision:
    """Test microsecond precision and rounding."""

    def test_fractional_seconds_with_microseconds(self):
        result = add_duration(datetime(2025, 3, 10, 0, 0, 0), "PT1.000001S")
        assert result == datetime(2025, 3, 10, 0, 0, 1, 1)

    def test_fractional_seconds_rounding(self):
        # 0.5000005 seconds should round to 500001 microseconds
        result = add_duration(datetime(2025, 3, 10, 0, 0, 0), "PT0.5000005S")
        assert result == datetime(2025, 3, 10, 0, 0, 0, 500001)

    def test_very_small_fraction_rounds_to_zero(self):
        # 0.0000001 seconds = 0.1 microseconds, rounds to 0
        result = add_duration(datetime(2025, 3, 10, 0, 0, 0), "PT0.0000001S")
        assert result == datetime(2025, 3, 10, 0, 0, 0, 0)

from datetime import datetime

import pytest
from isoduration import add_duration


# ==================== Syntax Validation ====================

class TestSyntaxValidation:
    """Test parsing and validation of ISO 8601 duration syntax."""

    # Valid formats
    def test_p_alone_is_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P")

    def test_pt_alone_is_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "PT")

    def test_p_with_no_time_component_after_t_is_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P1DT")

    def test_valid_days_only(self):
        assert add_duration(datetime(2025, 1, 1), "P1D") == datetime(2025, 1, 2)

    def test_valid_months_only(self):
        assert add_duration(datetime(2025, 1, 15), "P1M") == datetime(2025, 2, 15)

    def test_valid_years_only(self):
        assert add_duration(datetime(2025, 1, 15), "P1Y") == datetime(2026, 1, 15)

    def test_valid_weeks_only(self):
        assert add_duration(datetime(2025, 1, 1), "P1W") == datetime(2025, 1, 8)

    def test_valid_time_seconds_only(self):
        assert add_duration(datetime(2025, 1, 1, 12, 0, 0), "PT30S") == datetime(2025, 1, 1, 12, 0, 30)

    def test_valid_time_minutes_only(self):
        assert add_duration(datetime(2025, 1, 1, 12, 0), "PT30M") == datetime(2025, 1, 1, 12, 30)

    def test_valid_time_hours_only(self):
        assert add_duration(datetime(2025, 1, 1, 12, 0), "PT2H") == datetime(2025, 1, 1, 14, 0)

    def test_valid_weeks_cannot_combine_with_days(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P2W3D")

    def test_valid_weeks_cannot_combine_with_months(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P1M2W")

    def test_valid_weeks_cannot_combine_with_years(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P1Y2W")

    def test_invalid_weeks_with_time(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P2WPT1H")

    def test_sign_plus(self):
        assert add_duration(datetime(2025, 1, 1), "+P1D") == datetime(2025, 1, 2)

    def test_sign_minus(self):
        assert add_duration(datetime(2025, 1, 1), "-P1D") == datetime(2024, 12, 31)

    def test_whitespace_is_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P 1D")

    def test_component_sign_is_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P-1D")

    def test_lowercase_p_is_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "p1D")

    def test_lowercase_designator_is_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P1d")

    def test_m_before_t_is_months(self):
        result = add_duration(datetime(2025, 1, 15), "P1M")
        assert result.month == 2

    def test_m_after_t_is_minutes(self):
        result = add_duration(datetime(2025, 1, 1, 12, 0), "PT1M")
        assert result.minute == 1

    def test_components_must_be_in_order(self):
        # D before M is invalid
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P1D1M")

    def test_duplicate_component_year(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P1Y2Y")

    def test_duplicate_component_month(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P1M2M")

    def test_duplicate_component_day(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P1D2D")

    def test_duplicate_component_week(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P1W2W")

