class TestMonthEndHandling:
    """Test handling of month-end dates when duration involves months/years."""

    def test_jan31_plus_1_month_becomes_feb28(self):
        # 2025 is not a leap year
        result = add_duration(datetime(2025, 1, 31), "P1M")
        assert result == datetime(2025, 2, 28)

    def test_jan31_plus_1_month_becomes_feb29_leap_year(self):
        # 2024 is a leap year
        result = add_duration(datetime(2024, 1, 31), "P1M")
        assert result == datetime(2024, 2, 29)

    def test_mar31_plus_1_month_becomes_apr30(self):
        result = add_duration(datetime(2025, 3, 31), "P1M")
        assert result == datetime(2025, 4, 30)

    def test_jan31_plus_13_months_becomes_feb28_next_year(self):
        # 1 year 1 month = 13 months
        result = add_duration(datetime(2025, 1, 31), "P1Y1M")
        assert result == datetime(2026, 2, 28)

    def test_may31_plus_6_months_becomes_nov30(self):
        result = add_duration(datetime(2025, 5, 31), "P6M")
        assert result == datetime(2025, 11, 30)

    def test_month_end_with_leap_year_transition(self):
        # From leap year Feb 29 to non-leap year
        result = add_duration(datetime(2024, 1, 31), "P1Y")
        assert result == datetime(2025, 1, 31)

    def test_month_end_multiple_years(self):
        # 2024 is leap year, 2025 is not
        result = add_duration(datetime(2024, 2, 29), "P1Y1M")
        assert result == datetime(2025, 3, 29)

    def test_month_end_with_days_added(self):
        # Month end handling happens before days
        result = add_duration(datetime(2025, 1, 31), "P1M2D")
        # First: Jan 31 + 1 month = Feb 28 (month-end handling)
        # Then: Feb 28 + 2 days = Mar 2
        assert result == datetime(2025, 3, 2)

    def test_month_end_with_hours_added(self):
        # Month end, then add hours
        result = add_duration(datetime(2025, 1, 31, 10, 0, 0), "P1MT2H")
        assert result == datetime(2025, 2, 28, 12, 0, 0)

    def test_negative_month_to_month_end(self):
        # Mar 31 - 1 month: go back to Feb 28
        result = add_duration(datetime(2025, 3, 31), "-P1M")
        assert result == datetime(2025, 2, 28)

    def test_negative_months_then_days(self):
        # Mar 31 - (1 month + 1 day) = Feb 28 - 1 day = Feb 27
        result = add_duration(datetime(2025, 3, 31), "-P1M1D")
        assert result == datetime(2025, 2, 27)


