# ==================== Order of Operations ====================

class TestOrderOfOperations:
    """Test that components are applied in the correct order."""

    def test_months_before_days(self):
        # Month operations should happen before day operations
        # Jan 31 + 1 month = Feb 28 (month-end handling)
        # Then + 1 day = Mar 1
        result = add_duration(datetime(2025, 1, 31), "P1M1D")
        assert result == datetime(2025, 3, 1)

    def test_days_before_time(self):
        # Days should be added before time components
        result = add_duration(datetime(2025, 1, 1, 12, 0, 0), "P1DT2H")
        assert result == datetime(2025, 1, 2, 14, 0, 0)

    def test_negative_order_of_operations(self):
        # Mar 31 - 1 month = Feb 28 (month-end handling)
        # Then - 1 day = Feb 27
        # Then - 1 hour = Feb 27, 23:00 (of previous day) or Feb 27 - 1 hour
        result = add_duration(datetime(2025, 3, 31, 12, 0, 0), "-P1M1DT1H")
        # First: Mar 31, 12:00 - 1 month = Feb 28, 12:00 (month-end)
        # Then: Feb 28, 12:00 - 1 day = Feb 27, 12:00
        # Then: Feb 27, 12:00 - 1 hour = Feb 27, 11:00
        assert result == datetime(2025, 2, 27, 11, 0, 0)

    def test_weeks_as_days(self):
        # Weeks are converted to days (7 * weeks) and treated as days
        # So order is: months, then weeks+days, then time
        result = add_duration(datetime(2025, 1, 1), "P1W2D")
        # This should be invalid because weeks can't combine with other date components
        with pytest.raises(ValueError):
            pass


