class TestFractionalComponents:
    """Test fractional parts with . and , decimal separators."""

    def test_fractional_seconds_dot(self):
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT1.5S")
        assert result == datetime(2025, 3, 10, 8, 0, 1, 500000)

    def test_fractional_seconds_comma(self):
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT1,5S")
        assert result == datetime(2025, 3, 10, 8, 0, 1, 500000)

    def test_fractional_minutes(self):
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT1.5M")
        assert result == datetime(2025, 3, 10, 8, 1, 30)

    def test_fractional_hours(self):
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT1.5H")
        assert result == datetime(2025, 3, 10, 9, 30, 0)

    def test_fractional_days(self):
        result = add_duration(datetime(2025, 3, 10), "P0.5D")
        assert result == datetime(2025, 3, 10, 12, 0, 0)

    def test_fractional_weeks(self):
        result = add_duration(datetime(2025, 3, 10), "P0.5W")
        assert result == datetime(2025, 3, 13, 12, 0, 0)

    def test_fractional_on_last_component_only(self):
        # Fractional part is only allowed on the last component
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT30M1.5S")
        assert result == datetime(2025, 3, 10, 8, 30, 1, 500000)

    def test_fractional_zero_integer_seconds(self):
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT0.5S")
        assert result == datetime(2025, 3, 10, 8, 0, 0, 500000)

    def test_fractional_multiple_decimal_places(self):
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT1.123S")
        assert result == datetime(2025, 3, 10, 8, 0, 1, 123000)


# ============================================================================
# MONTH DAY OVERFLOW
# ============================================================================

class TestMonthDayOverflow:
    """Test day-of-month overflow when adding months."""

    def test_jan31_plus_1month_to_feb(self):
        # Jan 31 + 1 month → Feb 29 (leap year)
        assert add_duration(datetime(2024, 1, 31), "P1M") == datetime(2024, 2, 29)

    def test_jan31_plus_1month_to_feb_non_leap(self):
        # Jan 31 + 1 month → Feb 28 (non-leap year)
        assert add_duration(datetime(2025, 1, 31), "P1M") == datetime(2025, 2, 28)

    def test_march29_plus_12months_non_leap(self):
        # Mar 29 (leap year) + 12 months → Mar 28 (non-leap year)
        # Feb 29 is day 29, Mar has 31 days, so Feb 29 2024 + 12M = Mar 29 2025 (but non-leap has Mar 31 days)
        # Actually: 2024-02-29 is from 2024-01-31 + 1M (day overflow to Feb 29)
        # Then 2024-02-29 + 12M = 2025-02-28 (Feb non-leap has 28 days, so overflow)
        assert add_duration(datetime(2024, 2, 29), "P1Y") == datetime(2025, 2, 28)

    def test_may31_plus_1month_to_june(self):
        # May 31 + 1 month → June 30 (June has 30 days)
        assert add_duration(datetime(2025, 5, 31), "P1M") == datetime(2025, 6, 30)

    def test_multiple_month_overflow(self):
        # Jan 31 + 13 months (1 year 1 month) → Feb 29 (Feb has 29 days in leap year)
        assert add_duration(datetime(2024, 1, 31), "P1Y1M") == datetime(2025, 2, 28)

    def test_negative_month_overflow(self):
        # Mar 31 - 1 month → Feb 29 (leap year)
        assert add_duration(datetime(2024, 3, 31), "-P1M") == datetime(2024, 2, 29)

    def test_negative_month_overflow_non_leap(self):
        # Mar 31 - 1 month → Feb 28 (non-leap year)
        assert add_duration(datetime(2025, 3, 31), "-P1M") == datetime(2025, 2, 28)


