# ============================================================================
# MICROSECOND PRECISION AND ROUNDING
# ============================================================================

class TestMicrosecondPrecision:
    """Test microsecond precision and rounding."""

    def test_fractional_microseconds_exact(self):
        # 0.5 seconds = 500000 microseconds (exact)
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT0.5S")
        assert result.microsecond == 500000

    def test_very_small_fraction(self):
        # 0.0000001 seconds ≈ 0.1 microseconds (round to 0)
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT0.0000001S")
        # 0.1 microseconds should round to 0
        assert result == datetime(2025, 3, 10, 8, 0, 0)

    def test_rounding_up(self):
        # 0.0000005 seconds = 0.5 microseconds (round to nearest, ties to even: rounds to 0 or 1?)
        # Python's round() uses banker's rounding
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT0.0000005S")
        # 0.5 microseconds; banker's round to nearest even
        assert result.microsecond in [0, 1]  # Could round either way

    def test_fractional_minutes_gives_seconds(self):
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT1.5M")
        # 1.5 minutes = 90 seconds
        assert result == datetime(2025, 3, 10, 8, 1, 30)
        assert result.microsecond == 0

    def test_fractional_hours_gives_minutes_seconds(self):
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT0.75H")
        # 0.75 hours = 45 minutes
        assert result == datetime(2025, 3, 10, 8, 45, 0)

    def test_fractional_days_gives_hours(self):
        result = add_duration(datetime(2025, 3, 10, 0, 0, 0), "P0.25D")
        # 0.25 days = 6 hours
        assert result == datetime(2025, 3, 10, 6, 0, 0)

    def test_fractional_weeks_gives_days_hours(self):
        result = add_duration(datetime(2025, 3, 10, 0, 0, 0), "P0.1W")
        # 0.1 weeks = 0.7 days = 16.8 hours
        # Should be 16 hours + 0.8 * 3600 seconds = 16 hours + 2880 seconds = 16 hours 48 minutes
        expected = datetime(2025, 3, 10, 0, 0, 0) + timedelta(days=0.1)
        assert result == expected


