class TestNegativeMultipleComponents:
    """Test negative durations with order of operations."""

    def test_negative_months_then_days(self):
        # Mar 1 - (1 month + 1 day) = Feb 1 - 1 day = Jan 31
        assert add_duration(datetime(2024, 3, 1), "-P1M1D") == datetime(2024, 1, 31)

    def test_negative_months_with_overflow(self):
        # Mar 31 - 1 month = Feb 29 (leap year)
        assert add_duration(datetime(2024, 3, 31), "-P1M") == datetime(2024, 2, 29)

    def test_negative_years_and_months(self):
        # 2024-03-15 - 1Y2M = 2023-01-15
        assert add_duration(datetime(2024, 3, 15), "-P1Y2M") == datetime(2023, 1, 15)

    def test_negative_all_components(self):
        # 2024-03-15 10:30:00 - P1Y2M3DT4H5M6S
        assert add_duration(datetime(2024, 3, 15, 10, 30, 0), "-P1Y2M3DT4H5M6S") == datetime(2023, 1, 12, 6, 24, 54)


