# ============================================================================
# DATETIME RANGE LIMITS
# ============================================================================

class TestDatetimeRangeLimits:
    """Test overflow/underflow outside datetime range."""

    def test_overflow_max_datetime(self):
        # datetime.max is 9999-12-31 23:59:59.999999
        max_dt = datetime(9999, 12, 31, 23, 59, 59, 999999)
        with pytest.raises(ValueError):
            add_duration(max_dt, "P1D")

    def test_overflow_near_max(self):
        near_max = datetime(9999, 12, 31)
        with pytest.raises(ValueError):
            add_duration(near_max, "P1D")

    def test_underflow_min_datetime(self):
        # datetime.min is 1-1-1 00:00:00.000000
        min_dt = datetime(1, 1, 1)
        with pytest.raises(ValueError):
            add_duration(min_dt, "-P1D")

    def test_underflow_near_min(self):
        near_min = datetime(1, 1, 2)
        with pytest.raises(ValueError):
            add_duration(near_min, "-P2D")

    def test_overflow_with_months(self):
        # Year 10000 is outside range
        dt = datetime(9999, 1, 1)
        with pytest.raises(ValueError):
            add_duration(dt, "P1Y")

    def test_no_error_before_max(self):
        # This should work without error
        near_max = datetime(9999, 12, 30)
        result = add_duration(near_max, "P1D")
        assert result == datetime(9999, 12, 31)


