# M DESIGNATOR CONTEXT (before/after T)
# ============================================================================

class TestMDesignatorContext:
    """Test that M is interpreted correctly as months or minutes."""

    def test_m_before_t_is_months(self):
        # P1M means 1 month
        assert add_duration(datetime(2025, 1, 15), "P1M") == datetime(2025, 2, 15)

    def test_m_after_t_is_minutes(self):
        # PT1M means 1 minute
        assert add_duration(datetime(2025, 1, 15, 8, 0), "PT1M") == datetime(2025, 1, 15, 8, 1)

    def test_both_m_in_duration(self):
        # P1MT1M means 1 month + 1 minute
        assert add_duration(datetime(2025, 1, 15, 8, 0), "P1MT1M") == datetime(2025, 2, 15, 8, 1)

    def test_multiple_m_in_time_part(self):
        # Only one M allowed in time part (at most once per component type)
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 15), "PT1M2M")


# ============================================================================
# EDGE CASES
# ============================================================================

class TestEdgeCases:
    """Test various edge cases."""

    def test_zero_duration(self):
        # This would be invalid syntax (P with no component)
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 1, 1), "P0D")

    def test_very_large_number(self):
        # Very large days component
        result = add_duration(datetime(2025, 1, 1), "P9999999D")
        # Should either work or raise ValueError if overflow
        # This will likely overflow
        # Let's just verify it doesn't crash unexpectedly
        assert isinstance(result, datetime) or True  # Accept either result or error

    def test_leap_year_february_29_to_march(self):
        result = add_duration(datetime(2024, 2, 29), "P1D")
        assert result == datetime(2024, 3, 1)

    def test_leap_year_february_29_add_year(self):
        # 2024-02-29 + 1 year (non-leap) = 2025-02-28
        result = add_duration(datetime(2024, 2, 29), "P1Y")
        assert result == datetime(2025, 2, 28)

    def test_february_28_add_year_to_leap_year(self):
        # 2023-02-28 + 1 year (leap) = 2024-02-28 (not 29)
        # Actually 2024 is leap year, so this should give 2024-02-28
        result = add_duration(datetime(2023, 2, 28), "P1Y")
        assert result == datetime(2024, 2, 28)

    def test_decimal_separator_comma_time(self):
        result = add_duration(datetime(2025, 1, 1, 0, 0, 0), "PT0,5S")
        assert result == datetime(2025, 1, 1, 0, 0, 0, 500000)

    def test_zero_fractional_part(self):
        # PT1.0S means 1.0 seconds = 1 second
        result = add_duration(datetime(2025, 1, 1, 0, 0, 0), "PT1.0S")
        assert result == datetime(2025, 1, 1, 0, 0, 1)

    def test_midnight_transitions(self):
        result = add_duration(datetime(2025, 1, 1, 23, 0, 0), "PT2H")
        assert result == datetime(2025, 1, 2, 1, 0, 0)

    def test_year_boundary(self):
        result = add_duration(datetime(2024, 12, 31), "P1D")
        assert result == datetime(2025, 1, 1)

    def test_negative_crossing_year_boundary(self):
        result = add_duration(datetime(2025, 1, 1), "-P1D")
        assert result == datetime(2024, 12, 31)

    def test_month_boundary_negative(self):
        result = add_duration(datetime(2025, 2, 15), "-P20D")
        assert result == datetime(2025, 1, 26)
